// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title UserVault - Multi-tenant vault behind nginx reverse proxy
 * @notice The reverse proxy forwards X-Forwarded-For and appends a trusted
 *         relay signature. The proxy signs (userAddr, nonce, action) with its key.
 *         This contract verifies the proxy signature before executing actions.
 */
contract UserVault is Ownable {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct VaultEntry {
        uint256 balance;
        bytes32 secretHash;
        bool exists;
    }

    mapping(address => VaultEntry) private vaults;
    mapping(address => uint256) public nonces;

    address public trustedProxy;

    // Relay context passed from the reverse proxy layer
    struct RelayContext {
        address userAddr;
        uint256 nonce;
        bytes32 action;
        bytes proxySignature;
    }

    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event SecretUpdated(address indexed user);

    constructor(address _trustedProxy) Ownable(msg.sender) {
        trustedProxy = _trustedProxy;
    }

    function setTrustedProxy(address _proxy) external onlyOwner {
        trustedProxy = _proxy;
    }

    /**
     * @dev Core authorization: verifies the relay context signature matches
     *      the trusted proxy and that the nonce is valid for the user.
     */
    function _verifyRelayContext(RelayContext memory ctx) internal returns (bool) {
        // Verify nonce to prevent replay
        require(ctx.nonce == nonces[ctx.userAddr], "Invalid nonce");

        // Reconstruct the message the proxy should have signed
        bytes32 messageHash = keccak256(
            abi.encodePacked(ctx.userAddr, ctx.nonce, ctx.action)
        );

        // Apply Ethereum signed message prefix
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();

        // Recover signer and verify it's the trusted proxy
        address recovered = ethSignedHash.recover(ctx.proxySignature);
        require(recovered == trustedProxy, "Invalid proxy signature");

        // Increment nonce
        nonces[ctx.userAddr]++;

        return true;
    }

    /**
     * @dev Deposit funds into a user's vault via relay
     */
    function depositFor(RelayContext calldata ctx) external payable {
        require(ctx.action == keccak256("DEPOSIT"), "Wrong action");
        _verifyRelayContext(ctx);

        vaults[ctx.userAddr].balance += msg.value;
        vaults[ctx.userAddr].exists = true;

        emit Deposited(ctx.userAddr, msg.value);
    }

    /**
     * @dev Withdraw funds from a user's vault via relay
     * @param ctx The relay context from the proxy
     * @param amount The amount to withdraw
     * @param recipient Where to send the funds
     */
    function withdrawFor(
        RelayContext calldata ctx,
        uint256 amount,
        address payable recipient
    ) external {
        require(ctx.action == keccak256("WITHDRAW"), "Wrong action");
        _verifyRelayContext(ctx);

        require(vaults[ctx.userAddr].balance >= amount, "Insufficient balance");
        vaults[ctx.userAddr].balance -= amount;

        // Send to the recipient specified in the call
        (bool success, ) = recipient.call{value: amount}("");
        require(success, "Transfer failed");

        emit Withdrawn(ctx.userAddr, amount);
    }

    /**
     * @dev Update the secret hash stored in a user's vault
     */
    function updateSecretFor(
        RelayContext calldata ctx,
        bytes32 newSecretHash
    ) external {
        require(ctx.action == keccak256("UPDATE_SECRET"), "Wrong action");
        _verifyRelayContext(ctx);

        vaults[ctx.userAddr].secretHash = newSecretHash;

        emit SecretUpdated(ctx.userAddr);
    }

    /**
     * @dev View function - returns vault balance for a user.
     *      Access control: only the user themselves or owner can query.
     *      Uses tx.origin for the direct-call path (when user calls directly
     *      without going through the proxy relay).
     */
    function getVaultBalance(address user) external view returns (uint256) {
        require(
            msg.sender == user || msg.sender == owner() || tx.origin == user,
            "Not authorized"
        );
        return vaults[user].balance;
    }

    /**
     * @dev Batch operation: process multiple relay contexts atomically.
     *      The proxy batches requests for gas efficiency.
     *      Each context is independently verified.
     */
    function batchProcess(RelayContext[] calldata contexts, bytes[] calldata payloads) external {
        require(contexts.length == payloads.length, "Length mismatch");

        for (uint256 i = 0; i < contexts.length; i++) {
            RelayContext memory ctx = contexts[i];
            _verifyRelayContext(ctx);

            // Decode and execute based on action
            if (ctx.action == keccak256("DEPOSIT")) {
                // payload is empty for deposits (value comes from msg.value split)
                vaults[ctx.userAddr].exists = true;
            } else if (ctx.action == keccak256("UPDATE_SECRET")) {
                bytes32 newHash = abi.decode(payloads[i], (bytes32));
                vaults[ctx.userAddr].secretHash = newHash;
                emit SecretUpdated(ctx.userAddr);
            }
        }
    }

    /**
     * @dev Emergency function: user can withdraw directly without proxy
     *      if they can prove ownership via the stored secret.
     *      This bypasses the relay for disaster recovery.
     */
    function emergencyWithdraw(bytes32 secret) external {
        address user = msg.sender;
        require(vaults[user].exists, "No vault");
        require(
            keccak256(abi.encodePacked(secret)) == vaults[user].secretHash,
            "Invalid secret"
        );

        uint256 amount = vaults[user].balance;
        vaults[user].balance = 0;

        (bool success, ) = payable(user).call{value: amount}("");
        require(success, "Transfer failed");

        emit Withdrawn(user, amount);
    }

    receive() external payable {}
}
